int logfmt_parse_multi(const char *in, char **keys, char **vals, size_t max_pairs) {
    size_t num_pairs = 0;
    const char *start = in;

    while (num_pairs < max_pairs) {
        const char *end = strchr(start, ' ');
        if (!end) break;

        size_t pair_len = (size_t)(end - start);
        if (pair_len == 0) break;

        const char *eq = strchr(start, '=');
        if (!eq || eq >= end) break;

        size_t key_len = (size_t)(eq - start);
        size_t val_len = pair_len - key_len - 1;

        if (keys[num_pairs]) free(keys[num_pairs]);
        keys[num_pairs] = malloc(key_len + 1);
        if (!keys[num_pairs]) return -1;
        strncpy(keys[num_pairs], start, key_len);
        keys[num_pairs][key_len] = '\0';

        if (vals[num_pairs]) free(vals[num_pairs]);
        vals[num_pairs] = malloc(val_len + 1);
        if (!vals[num_pairs]) return -1;
        strncpy(vals[num_pairs], eq + 1, val_len);
        vals[num_pairs][val_len] = '\0';

        num_pairs++;
        start = end + 1;
    }

    return num_pairs;
}

