int logfmt_nth_token(const char *line, int n, char *out, size_t out_sz) {
    if (n < 0) return -1;

    const char *token = line;
    int count = 0;

    while (token) {
        if (count == n) {
            break;
        }

        // Find end of current token
        const char *end = strchr(token, ' ');
        if (!end) {
            end = token + strlen(token);
            break;
        }

        // Move to start of next token
        token = end + 1;
        count++;
    }

    if (!token) return -1;

    // Copy token to output buffer
    size_t len = (size_t)(end - token);
    if (len >= out_sz) len = out_sz - 1;
    strncpy(out, token, len);
    out[len] = '\0';

    return 0;
}

